# Arch dependencies of the Qt rewrite's host libraries, for the AUR package
# hikarisub-bin (installers spec 5.4, 5.5). "<soname> <package>"; read by
# resolve-deps.sh through aur/render-pkgbuild.sh. Every soname the app tree
# needs from the host must have a line. Owners checked with pacman -F.
ld-linux-x86-64.so.2 @glibc
libc.so.6 @glibc
libm.so.6 @glibc
libdl.so.2 @glibc
libpthread.so.0 @glibc
librt.so.1 @glibc
libresolv.so.2 @glibc
libstdc++.so.6 libstdc++
libgcc_s.so.1 libgcc
libEGL.so.1 libglvnd
libGL.so.1 libglvnd
libOpenGL.so.0 libglvnd
libGLX.so.0 libglvnd
libgbm.so.1 mesa
libdrm.so.2 libdrm
libX11.so.6 libx11
libX11-xcb.so.1 libx11
libXext.so.6 libxext
libXrandr.so.2 libxrandr
libxcb.so.1 libxcb
libxcb-glx.so.0 libxcb
libxcb-randr.so.0 libxcb
libxcb-render.so.0 libxcb
libxcb-shape.so.0 libxcb
libxcb-shm.so.0 libxcb
libxcb-sync.so.1 libxcb
libxcb-xfixes.so.0 libxcb
libxcb-xinput.so.0 libxcb
libxcb-xkb.so.1 libxcb
libxcb-cursor.so.0 xcb-util-cursor
libxcb-icccm.so.4 xcb-util-wm
libxcb-image.so.0 xcb-util-image
libxcb-keysyms.so.1 xcb-util-keysyms
libxcb-render-util.so.0 xcb-util-renderutil
libxcb-util.so.1 xcb-util
libxkbcommon.so.0 libxkbcommon
libxkbcommon-x11.so.0 libxkbcommon-x11
libwayland-client.so.0 wayland
libwayland-cursor.so.0 wayland
libwayland-egl.so.1 wayland
libfontconfig.so.1 fontconfig
libfreetype.so.6 freetype2
libglib-2.0.so.0 glib2
libgthread-2.0.so.0 glib2
libdbus-1.so.3 dbus
libasound.so.2 alsa-lib
libpulse.so.0 libpulse
libz.so.1 zlib
libzstd.so.1 zstd
libbz2.so.1 bzip2
libbrotlidec.so.1 brotli
libgssapi_krb5.so.2 krb5
